mapper.insert:
INSERT INTO place_order_draft (
    branch_code,
    status
)
VALUES (
    #{branchCode},
    #{status}
)

mapper.delete:
DELETE FROM place_order_draft_detail
WHERE draft_id = #{draftId}
  AND material_code = #{materialCode}

mapper.update:
UPDATE place_order_draft_detail
SET requested_qty = #{requestedQty}
WHERE draft_id = #{draftId}
  AND material_code = #{materialCode}

UPDATE place_order_draft
SET po_id = #{poId},
	status = #{status}
WHERE draft_id = #{draftId}

mapper.select:
SELECT m.material_code AS materialCode, m.material_group_id AS materialGroupId, m.material_name AS materialName, m.unit AS unit FROM material m
m.material_group_id = #{_parameter}
ORDER BY m.material_name
